import os

from .exception import SSHExecutionError, SymbolicLinkError
from .fsmaccess import FsmAccess, EstablishSSHinMethodContext


class WtsFsmAccess(FsmAccess):

    def __init__(self, connection_manager, fsm_services):
        """ Prepare connection to Fsm.

        :param ConnectionManager connection_manager:        Connection Manager (e.g. ssh, telnet).
        :param Fsmservices fsm_services:                    Fsm services.

        """
        super(WtsFsmAccess, self).__init__(connection_manager)
        self._fsm_service = fsm_services

    @EstablishSSHinMethodContext
    def get_wts_fsm_config_file(self, dst, partition='active'):
        """Copy config file from WTS to specified localization on PC.

        :param string dst:  Destination directory path.

        :return:            Source and destination path.
        :rtype:             tuple
        """
        link = self._get_symbolic_link(partition_path=self._get_partition_path(partition))
        return self._get_file(src=link, dst=dst)

    @EstablishSSHinMethodContext
    def put_wts_fsm_config_file(self, src, partition='active'):
        """Copy config file from specified localization on PC to WTS.

        :param string src:              Source file path.
        :param string partition:         Partition type, default: active.

        :return:                        Source and destination path.
        :rtype:                         tuple
        """

        partition_path = self._get_partition_path(partition)
        if partition == 'passive':
            self._make_writeable_passive_partition()
        dst_file_name = os.path.basename(src)
        dst_file_name = 'uploaded_' + dst_file_name if dst_file_name == 'iphy.xml' else dst_file_name
        src_dst_paths = self._put_file(src=src, dst='%s/simmode/%s' % (partition_path, dst_file_name))
        self._make_symbolic_link(partition_path=partition_path, linked_file=dst_file_name)
        return src_dst_paths

    @EstablishSSHinMethodContext
    def get_fsm_sw_version(self, partition='active'):
        """Get WTS software version.

        :param string patition:          Partition type, default: active.

        :return:                         WTS software version.
        :rtype:                          string
        """
        swversion = self._get_fsm_sw_version(partition)
        return 'WTS_' + swversion.split('_WTS_')[-1]

    @EstablishSSHinMethodContext
    def set_writeable_wts_passive_partition(self):
        """Set read-write permission mode for WTS passive partition."""
        self._make_writeable_passive_partition()

    def _get_symbolic_link(self, partition_path):
        try:
            return self._execute_ssh_command("readlink -f %s/simmode/iphy.xml" % partition_path)
        except SSHExecutionError:
            raise SymbolicLinkError("Symbolic link iphy.xml does not exist.")

    def _make_symbolic_link(self, partition_path, linked_file):
        try:
            return self._execute_ssh_command("ln -f -s %s/simmode/%s %s/simmode/iphy.xml" % (partition_path, linked_file, partition_path))
        except SSHExecutionError as e:
            raise SymbolicLinkError(str(e))

    def enable_ssh(self, timeout=0):
        """Enable SSH services on FSM.

        :param integer timeout        Timeout in enabling SSH
        """
        return self._fsm_service.enable_ssh(timeout=timeout)
